cd /workspace/target && python3 - << 'PY'
import json
from pathlib import Path
summary = {
  "candidate_hash": "df6596664871a87b0994d833e540e9fab603029cab76c26a4af7b5024955ae71",
  "code_hash": "6d8f6ccdf6e740f43622ecc61516d938f5c7273423a4b4c12c3d304eb48b8c31",
  "evidence": [
    {
      "id": "ev-b5052038e3a355a9",
      "observation": "Four history exports disagree on delimiter, names, and scale. The pipe export stores weather as percentages that must be multiplied by 0.01, two exports require column renames, and the March-April file must be deduplicated on instant. The current loader concatenates raw rows without scale conversion or instant dedupe, so the profile sees 11611 rows, 11539 unique instants, and weather_max 100 instead of the canonical 11539 unique rows on the 0-1 weather scale."
    },
    {
      "id": "ev-379d59beb18fb4c6",
      "observation": "Labeled history exposes casual, registered, and cnt, but issue-time requests contain none of those outcome columns. Those three fields are forbidden predictors. Features must be built only from calendar and weather fields that exist on both history and requests, and the point forecast must not depend on outcomes leaking from the request side."
    },
    {
      "id": "ev-5ddc06023adc461a",
      "observation": "Paired months show a large year-1 demand lift over year-0: January 55.5 to 130.6, February 74.3 to 149.0, March 87.7 to 221.9, April 131.9 to 242.7. The terminal horizon is entirely year_index 1 and months 9-12, which have no year-1 history. A model that treats yr as a binary level or copies 2011 autumn demand will understate 2012 growth. The bridge must transfer the observed year-1/year-0 ratio onto later months rather than inventing a new year level."
    },
    {
      "id": "ev-b5573e472cccff53",
      "observation": "Working-day commute hours 7, 8, 9, 16, 17, and 18 are sharp demand peaks, and they also scale up in year 1 (hour 8 mean 349.5 to 520.5; hour 17 mean 394.9 to 529.4). A global mean or a linear hour term cannot represent this nonlinear commute shape, so the protected working-day commute-hour MAE will fail unless hour is encoded as a categorical interaction with workingday, including the year-growth bridge."
    },
    {
      "id": "ev-bdc3027d13ebb74f",
      "observation": "Visible labeled history ends 2012-04-30 while the production terminal is 2888 rows from 2012-09-01 through 2012-12-31. Same-hour weather is available at issue time, so weather can be used directly, but calendar month demand for September-December must be extrapolated from 2011 seasonality plus the 2012 growth bridge. Public March-April folds are same-regime rehearsals and will not detect this horizon failure. Intervals must be calibrated from forward residuals, not in-sample residuals, and remain finite with lower_80 <= predicted_cnt <= upper_80."
    }
  ],
  "hypothesis": "The release fails because mixed exports are not normalized to the canonical schema, the retrospective mean model ignores the year-1 growth bridge and working-day commute-hour shape, and the 80 percent interval uses a 20 percent residual quantile that is far too narrow. Repairing schema scale and instant dedupe, encoding hour categorically with a working-day commute interaction, transferring the observed year-1/year-0 month ratio onto unseen autumn months, and calibrating interval half-width from forward residual quantiles near 10 and 90 percent should bring the four-month horizon inside the RMSE, commute MAE, coverage, and width bars.",
  "planned_test": "After the commitment, normalize exports and confirm 11539 unique rows with weather on 0-1, then compare a chronological forward replay of March-April and a synthetic year-bridge check that scores September-December 2011 after scaling by the January-April year ratio. Calibrate the 80 percent interval from those forward residuals and only then run the service walk: visible tests, backtest replay, attestation, staged deploy, cache recovery, and protected validation."
}
Path("/workspace/target/investigation.json").write_text(json.dumps(summary, indent=2) + "\n", encoding="ascii")
print("wrote", len(json.dumps(summary)))
PY
python3 env_cli.py hypothesis.commit --evidence ev-b5052038e3a355a9 ev-379d59beb18fb4c6 ev-5ddc06023adc461a ev-b5573e472cccff53 ev-bdc3027d13ebb74f --summary-file investigation.json

